insert into public.doctors(hospital_id,full_name,specialty,experience_years,image_url,source_url,is_verified,verification_status)
select h.id,c.full_name,c.specialty,0,'',c.source_url,true,'named_in_user_research_source'
from clinician_rows c join public.hospitals h on lower(h.name)=lower(c.hospital_name) and lower(h.city)=lower(c.city)
where not exists(select 1 from public.doctors d where lower(d.full_name)=lower(c.full_name) and d.hospital_id=h.id);
